// retry.ts
export type Sleeper = (ms: number, signal?: AbortSignal) => Promise<void>;
export type RandomSource = () => number;

export type JitterStrategy = "none" | "full";

export interface RetryOptions {
  retries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  factor?: number;
  jitter?: JitterStrategy;
  signal?: AbortSignal;
  sleep?: Sleeper;
  random?: RandomSource;
  isRetryable?: (error: unknown, attempt: number) => boolean;
  onRetry?: (info: { attempt: number; delayMs: number; error: unknown }) => void;
}

export class RetryAbortedError extends Error {
  constructor(message = "Retry aborted") { super(message); this.name = "RetryAbortedError"; }
}

export class RetryError extends Error {
  constructor(public readonly attempts: number, public readonly lastError: unknown) {
    super(`Failed after ${attempts} attempt(s)`);
    this.name = "RetryError";
  }
}
```

