export async function retry<T>(fn: (attempt: number) => Promise<T>, opts: RetryOptions = {}): Promise<T> {
  const {
    retries = 3,
    baseDelayMs = 100,
    maxDelayMs = Infinity,
    factor = 2,
    jitter = "full",
    signal,
    sleep = defaultSleep,
    random = Math.random,
    isRetryable = () => true,
    onRetry,
  } = opts;

  throwIfAborted(signal);

  let attempt = 0;
  let lastError: unknown;
  while (true) {
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;
      if (isAbortError(error)) throw error; // hmm, maybe not
      if (attempt >= retries || !isRetryable(error, attempt)) {
        throw new RetryError(attempt + 1, error);
      }
      const delay = computeDelay(attempt, ...);
      onRetry?.({ attempt, delayMs: delay, error });
      await sleep(delay, signal); // may throw RetryAbortedError
      attempt += 1;
    }
  }
}
```

